Object.assign(window.AUTO_DATA=window.AUTO_DATA||{},{"S_v_y0":{"y":2026,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2026–2027 · môn Toán","note":"Cấu trúc theo chương trình GDPT 2018: 5 bài tự luận, 120 phút, thang 10 (thống kê – xác suất, biểu thức chứa căn, bài toán thực tế, hình học thực tế và đường tròn, tối ưu).","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 40 học sinh được ghép nhóm: [140; 145): 9; [145; 150): 6; [150; 155): 8; [155; 160): 8; [160; 165): 9. Tần số tương đối của nhóm [145; 150) là bao nhiêu phần trăm?","a":"15","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["6 : 40 × 100% = 15%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 35 tấm thẻ đánh số từ 1 đến 35. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 7 (viết dạng a/b tối giản).","a":"1/7","f":true,"p":0.75,"h":"Đếm các bội của 7.","s":["Có 5 bội của 7 từ 1 đến 35.","P = 5/35 = 1/7."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 9)/(√x − 4) với x ≥ 0, x ≠ 16. Tính giá trị của A khi x = 361 (viết dạng a/b nếu không nguyên).","a":"28/15","f":true,"p":0.5,"h":"√361 = 19.","s":["A = (19 + 9)/(19 − 4) = 28/15."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 6) + 4√x/(√x − 6) − (5x + 14√x + 24)/(x − 36) với x ≥ 0, x ≠ 36. Rút gọn B ta được","o":["B = 4√x/(√x + 6)","B = 4/(√x − 6)","B = (√x + 4)/(√x + 6)","B = 4/(√x + 6)"],"a":3,"p":0.5,"h":"Quy đồng với mẫu chung x − 36 = (√x − 6)(√x + 6).","s":["Tử số sau khi quy đồng: 4√x − 24 = 4(√x − 6).","B = 4(√x − 6)/[(√x − 6)(√x + 6)] = 4/(√x + 6)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 4/(√x + 6) (x ≥ 0, x ≠ 36), có bao nhiêu số nguyên x để B > 1/2?","a":"4","f":true,"p":0.5,"h":"B > 1/2 ⇔ √x + 6 < 8.","s":["√x < 2 ⇔ 0 ≤ x < 4.","Có 4 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 33 bông hoa gồm hoa hồng và hoa cúc hết 352 nghìn đồng. Giá một bông hồng là 12 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"11","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 33; 12x + 10y = 352.","x = 11, y = 22."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 33 bông hoa, 352 nghìn đồng, hồng 12 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"22","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["33 − 11 = 22."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 5 m và diện tích 300 m². Tính chiều rộng mảnh vườn (m).","a":"15","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 5) = 300 ⇔ x² + 5x − 300 = 0.","x = 15 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 9x + 9 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"63","f":true,"p":0.5,"h":"x₁ + x₂ = 9, x₁x₂ = 9.","s":["(x₁ + x₂)² − 2x₁x₂ = 81 − 18 = 63."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình nón thực tế","q":"Một chiếc nón lá có dạng hình nón với bán kính đáy 7 dm, chiều cao 15 dm. Tính thể tích phần không gian bên trong nón (dm³), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"769.3","f":true,"p":1,"h":"V = πr²h/3.","s":["3,14 × 7² × 15 : 3 ≈ 769,3."],"m":"Nón bằng 1/3 trụ cùng đáy, cùng cao."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 62°. Tính số đo góc ABC (độ).","a":"28","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 62° = 28°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 120 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 174 cm. Tính độ dài MA (cm).","a":"126","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(30276 − 14400) = 126 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 13 cm), góc ở tâm AOB = 135°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"30.61","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 13 × 135 : 180 ≈ 30,61 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 60 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"450","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(60 − 2x), lớn nhất khi x = 15.","Smax = 15 × 30 = 450 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_y1":{"y":2025,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2025–2026 · môn Toán","note":"Cấu trúc theo chương trình GDPT 2018: 5 bài tự luận, 120 phút, thang 10 (thống kê – xác suất, biểu thức chứa căn, bài toán thực tế, hình học thực tế và đường tròn, tối ưu).","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 40 học sinh được ghép nhóm: [140; 145): 10; [145; 150): 4; [150; 155): 9; [155; 160): 10; [160; 165): 7. Tần số tương đối của nhóm [145; 150) là bao nhiêu phần trăm?","a":"10","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["4 : 40 × 100% = 10%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 60 tấm thẻ đánh số từ 1 đến 60. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 3 (viết dạng a/b tối giản).","a":"1/3","f":true,"p":0.75,"h":"Đếm các bội của 3.","s":["Có 20 bội của 3 từ 1 đến 60.","P = 20/60 = 1/3."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 6)/(√x − 4) với x ≥ 0, x ≠ 16. Tính giá trị của A khi x = 121 (viết dạng a/b nếu không nguyên).","a":"17/7","f":true,"p":0.5,"h":"√121 = 11.","s":["A = (11 + 6)/(11 − 4) = 17/7."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 2) + 4√x/(√x − 2) − (5x − 1√x + 14)/(x − 4) với x ≥ 0, x ≠ 4. Rút gọn B ta được","o":["B = 7/(√x − 2)","B = 7√x/(√x + 2)","B = (√x + 7)/(√x + 2)","B = 7/(√x + 2)"],"a":3,"p":0.5,"h":"Quy đồng với mẫu chung x − 4 = (√x − 2)(√x + 2).","s":["Tử số sau khi quy đồng: 7√x − 14 = 7(√x − 2).","B = 7(√x − 2)/[(√x − 2)(√x + 2)] = 7/(√x + 2)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 7/(√x + 2) (x ≥ 0, x ≠ 4), có bao nhiêu số nguyên x để B > 7/5?","a":"8","f":true,"p":0.5,"h":"B > 7/5 ⇔ √x + 2 < 5.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Loại x = 4.","Có 8 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 34 bông hoa gồm hoa hồng và hoa cúc hết 368 nghìn đồng. Giá một bông hồng là 12 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"14","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 34; 12x + 10y = 368.","x = 14, y = 20."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 34 bông hoa, 368 nghìn đồng, hồng 12 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"20","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["34 − 14 = 20."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 2 m và diện tích 48 m². Tính chiều rộng mảnh vườn (m).","a":"6","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 2) = 48 ⇔ x² + 2x − 48 = 0.","x = 6 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 11x + 17 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"87","f":true,"p":0.5,"h":"x₁ + x₂ = 11, x₁x₂ = 17.","s":["(x₁ + x₂)² − 2x₁x₂ = 121 − 34 = 87."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 1,5 m, chiều cao 2 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"14.13","f":true,"p":1,"h":"V = πr²h.","s":["3,14 × 1,5² × 2 ≈ 14,13 m³."],"m":"Bình phương bán kính, không phải đường kính."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 64°. Tính số đo góc ABC (độ).","a":"26","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 64° = 26°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 5 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 13 cm. Tính độ dài MA (cm).","a":"12","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(169 − 25) = 12 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 15 cm), góc ở tâm AOB = 150°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"39.25","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 15 × 150 : 180 ≈ 39,25 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 248 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"7688","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(248 − 2x), lớn nhất khi x = 62.","Smax = 62 × 124 = 7688 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_y2":{"y":2024,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2024–2025 · môn Toán","note":"Cấu trúc đề Hà Nội giai đoạn 2019–2024: Bài I rút gọn biểu thức (2 đ), Bài II giải toán bằng cách lập phương trình/hệ + hình học thực tế (2,5 đ), Bài III hệ phương trình và parabol (2 đ), Bài IV hình học đường tròn (3 đ), Bài V cực trị (0,5 đ). 120 phút.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 8)/(√x − 2) với x ≥ 0, x ≠ 4. Tính giá trị của A khi x = 169 (viết dạng a/b nếu không nguyên).","a":"21/11","f":true,"p":0.5,"h":"√169 = 13.","s":["A = (13 + 8)/(13 − 2) = 21/11."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 3) + 4√x/(√x − 3) − (5x − 3√x + 36)/(x − 9) với x ≥ 0, x ≠ 9. Rút gọn B ta được","o":["B = 12/(√x + 3)","B = (√x + 12)/(√x + 3)","B = 12√x/(√x + 3)","B = 12/(√x − 3)"],"a":0,"p":1,"h":"Quy đồng với mẫu chung x − 9 = (√x − 3)(√x + 3).","s":["Tử số sau khi quy đồng: 12√x − 36 = 12(√x − 3).","B = 12(√x − 3)/[(√x − 3)(√x + 3)] = 12/(√x + 3)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 12/(√x + 3) (x ≥ 0, x ≠ 9), có bao nhiêu số nguyên x để B > 2?","a":"9","f":true,"p":0.5,"h":"B > 2 ⇔ √x + 3 < 6.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Có 9 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 40 bông hoa gồm hoa hồng và hoa cúc hết 990 nghìn đồng. Giá một bông hồng là 30 nghìn, một bông cúc là 20 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"19","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 40; 30x + 20y = 990.","x = 19, y = 21."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 40 bông hoa, 990 nghìn đồng, hồng 30 nghìn, cúc 20 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"21","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["40 − 19 = 21."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 7 m và diện tích 294 m². Tính chiều rộng mảnh vườn (m).","a":"14","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 7) = 294 ⇔ x² + 7x − 294 = 0.","x = 14 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 1,1 m, chiều cao 1,2 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"4.56","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 1,1² × 1,2 ≈ 4,56 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 2/(x − 1) + 4/(y + 1) = 1 và 1/(x − 1) − 1/(y + 1) = 1/8. Tính x + y.","a":"12","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/4, v = 1/8.","x = 5, y = 7 ⇒ x + y = 12."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 8x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 62.","a":"2","f":true,"p":1,"h":"Phương trình hoành độ x² − 8x + m − 1 = 0.","s":["Δ′ = 16 − m + 1 > 0 ⇔ m < 17.","x₁² + x₂² = 64 − 2(m − 1) = 62 ⇒ m = 2 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 22°. Tính số đo góc ABC (độ).","a":"68","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 22° = 68°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 36 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 39 cm. Tính độ dài MA (cm).","a":"15","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(1521 − 1296) = 15 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 14 cm), góc ở tâm AOB = 60°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"14.65","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 14 × 60 : 180 ≈ 14,65 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 9. Tìm giá trị nhỏ nhất của P = x + 27/x.","a":"12","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √27.","s":["Với x ≥ 9 > √27, P tăng theo x.","Pmin = P(9) = 9 + 27/9 = 12."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_y3":{"y":2023,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2023–2024 · môn Toán","note":"Cấu trúc đề Hà Nội giai đoạn 2019–2024: Bài I rút gọn biểu thức (2 đ), Bài II giải toán bằng cách lập phương trình/hệ + hình học thực tế (2,5 đ), Bài III hệ phương trình và parabol (2 đ), Bài IV hình học đường tròn (3 đ), Bài V cực trị (0,5 đ). 120 phút.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 7)/(√x − 4) với x ≥ 0, x ≠ 16. Tính giá trị của A khi x = 256 (viết dạng a/b nếu không nguyên).","a":"23/12","f":true,"p":0.5,"h":"√256 = 16.","s":["A = (16 + 7)/(16 − 4) = 23/12."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 4) + 3√x/(√x − 4) − (4x − 3√x + 44)/(x − 16) với x ≥ 0, x ≠ 16. Rút gọn B ta được","o":["B = (√x + 11)/(√x + 4)","B = 11/(√x − 4)","B = 11√x/(√x + 4)","B = 11/(√x + 4)"],"a":3,"p":1,"h":"Quy đồng với mẫu chung x − 16 = (√x − 4)(√x + 4).","s":["Tử số sau khi quy đồng: 11√x − 44 = 11(√x − 4).","B = 11(√x − 4)/[(√x − 4)(√x + 4)] = 11/(√x + 4)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 11/(√x + 4) (x ≥ 0, x ≠ 16), có bao nhiêu số nguyên x để B > 11/6?","a":"4","f":true,"p":0.5,"h":"B > 11/6 ⇔ √x + 4 < 6.","s":["√x < 2 ⇔ 0 ≤ x < 4.","Có 4 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 55 bông hoa gồm hoa hồng và hoa cúc hết 1500 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 18 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"30","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 55; 35x + 18y = 1500.","x = 30, y = 25."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 55 bông hoa, 1500 nghìn đồng, hồng 35 nghìn, cúc 18 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"25","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["55 − 30 = 25."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Bài toán làm chung","q":"Hai vòi nước cùng chảy vào một bể cạn. Vòi thứ nhất chảy riêng đầy bể trong 7 giờ, vòi thứ hai trong 9 giờ. Hỏi cả hai vòi cùng chảy thì bao nhiêu giờ đầy bể?","a":"63/16","f":true,"p":1,"h":"Cộng năng suất mỗi giờ.","s":["1/7 + 1/9 = 16/63 bể/giờ.","Thời gian: 63/16 giờ."],"m":"Năng suất là phần bể mỗi giờ."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 0,5 m, chiều cao 0,9 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"0.71","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 0,5² × 0,9 ≈ 0,71 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 1/(x − 1) + 5/(y + 1) = 13/12 và 2/(x − 1) + 3/(y + 1) = 1. Tính x + y.","a":"10","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/4, v = 1/6.","x = 5, y = 5 ⇒ x + y = 10."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 2x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 18.","a":"-6","f":true,"p":1,"h":"Phương trình hoành độ x² − 2x + m − 1 = 0.","s":["Δ′ = 1 − m + 1 > 0 ⇔ m < 2.","x₁² + x₂² = 4 − 2(m − 1) = 18 ⇒ m = -6 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 24°. Tính số đo góc ABC (độ).","a":"66","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 24° = 66°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 96 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 100 cm. Tính độ dài MA (cm).","a":"28","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(10000 − 9216) = 28 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 5 cm), góc ở tâm AOB = 90°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"7.85","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 5 × 90 : 180 ≈ 7,85 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 3. Tìm giá trị nhỏ nhất của P = x + 6/x.","a":"5","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √6.","s":["Với x ≥ 3 > √6, P tăng theo x.","Pmin = P(3) = 3 + 6/3 = 5."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_y4":{"y":2022,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2022–2023 · môn Toán","note":"Cấu trúc đề Hà Nội giai đoạn 2019–2024: Bài I rút gọn biểu thức (2 đ), Bài II giải toán bằng cách lập phương trình/hệ + hình học thực tế (2,5 đ), Bài III hệ phương trình và parabol (2 đ), Bài IV hình học đường tròn (3 đ), Bài V cực trị (0,5 đ). 120 phút.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 9)/(√x − 3) với x ≥ 0, x ≠ 9. Tính giá trị của A khi x = 324 (viết dạng a/b nếu không nguyên).","a":"9/5","f":true,"p":0.5,"h":"√324 = 18.","s":["A = (18 + 9)/(18 − 3) = 9/5."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 6) + 3√x/(√x − 6) − (4x + 2√x + 60)/(x − 36) với x ≥ 0, x ≠ 36. Rút gọn B ta được","o":["B = 10/(√x + 6)","B = 10/(√x − 6)","B = 10√x/(√x + 6)","B = (√x + 10)/(√x + 6)"],"a":0,"p":1,"h":"Quy đồng với mẫu chung x − 36 = (√x − 6)(√x + 6).","s":["Tử số sau khi quy đồng: 10√x − 60 = 10(√x − 6).","B = 10(√x − 6)/[(√x − 6)(√x + 6)] = 10/(√x + 6)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 10/(√x + 6) (x ≥ 0, x ≠ 36), có bao nhiêu số nguyên x để B > 5/4?","a":"4","f":true,"p":0.5,"h":"B > 5/4 ⇔ √x + 6 < 8.","s":["√x < 2 ⇔ 0 ≤ x < 4.","Có 4 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 29 bông hoa gồm hoa hồng và hoa cúc hết 475 nghìn đồng. Giá một bông hồng là 20 nghìn, một bông cúc là 15 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"8","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 29; 20x + 15y = 475.","x = 8, y = 21."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 29 bông hoa, 475 nghìn đồng, hồng 20 nghìn, cúc 15 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"21","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["29 − 8 = 21."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 2 m và diện tích 195 m². Tính chiều rộng mảnh vườn (m).","a":"13","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 2) = 195 ⇔ x² + 2x − 195 = 0.","x = 13 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 1,5 m, chiều cao 3,1 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"21.9","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 1,5² × 3,1 ≈ 21,9 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 1/(x − 1) + 4/(y + 1) = 27/35 và 3/(x − 1) + 1/(y + 1) = 26/35. Tính x + y.","a":"12","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/5, v = 1/7.","x = 6, y = 6 ⇒ x + y = 12."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 4x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 42.","a":"-12","f":true,"p":1,"h":"Phương trình hoành độ x² − 4x + m − 1 = 0.","s":["Δ′ = 4 − m + 1 > 0 ⇔ m < 5.","x₁² + x₂² = 16 − 2(m − 1) = 42 ⇒ m = -12 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 18°. Tính số đo góc ABC (độ).","a":"72","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 18° = 72°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 72 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 78 cm. Tính độ dài MA (cm).","a":"30","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(6084 − 5184) = 30 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 5 cm), góc ở tâm AOB = 72°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"6.28","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 5 × 72 : 180 ≈ 6,28 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 8. Tìm giá trị nhỏ nhất của P = x + 9/x.","a":"73/8","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √9.","s":["Với x ≥ 8 > √9, P tăng theo x.","Pmin = P(8) = 8 + 9/8 = 73/8."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_y5":{"y":2021,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2021–2022 · môn Toán","note":"Cấu trúc đề Hà Nội giai đoạn 2019–2024: Bài I rút gọn biểu thức (2 đ), Bài II giải toán bằng cách lập phương trình/hệ + hình học thực tế (2,5 đ), Bài III hệ phương trình và parabol (2 đ), Bài IV hình học đường tròn (3 đ), Bài V cực trị (0,5 đ). 120 phút.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 7)/(√x − 5) với x ≥ 0, x ≠ 25. Tính giá trị của A khi x = 144 (viết dạng a/b nếu không nguyên).","a":"19/7","f":true,"p":0.5,"h":"√144 = 12.","s":["A = (12 + 7)/(12 − 5) = 19/7."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 3) + √x/(√x − 3) − (2x − 8√x + 24)/(x − 9) với x ≥ 0, x ≠ 9. Rút gọn B ta được","o":["B = (√x + 8)/(√x + 3)","B = 8√x/(√x + 3)","B = 8/(√x − 3)","B = 8/(√x + 3)"],"a":3,"p":1,"h":"Quy đồng với mẫu chung x − 9 = (√x − 3)(√x + 3).","s":["Tử số sau khi quy đồng: 8√x − 24 = 8(√x − 3).","B = 8(√x − 3)/[(√x − 3)(√x + 3)] = 8/(√x + 3)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 8/(√x + 3) (x ≥ 0, x ≠ 9), có bao nhiêu số nguyên x để B > 4/3?","a":"9","f":true,"p":0.5,"h":"B > 4/3 ⇔ √x + 3 < 6.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Có 9 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 40 bông hoa gồm hoa hồng và hoa cúc hết 388 nghìn đồng. Giá một bông hồng là 12 nghìn, một bông cúc là 8 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"17","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 40; 12x + 8y = 388.","x = 17, y = 23."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 40 bông hoa, 388 nghìn đồng, hồng 12 nghìn, cúc 8 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"23","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["40 − 17 = 23."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 3 m và diện tích 54 m². Tính chiều rộng mảnh vườn (m).","a":"6","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 3) = 54 ⇔ x² + 3x − 54 = 0.","x = 6 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 1,3 m, chiều cao 2,6 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"13.8","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 1,3² × 2,6 ≈ 13,8 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 6/(x − 1) + 4/(y + 1) = 58/9 và 1/(x − 1) − 2/(y + 1) = 7/9. Tính x + y.","a":"10","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1, v = 1/9.","x = 2, y = 8 ⇒ x + y = 10."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 8x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 74.","a":"-4","f":true,"p":1,"h":"Phương trình hoành độ x² − 8x + m − 1 = 0.","s":["Δ′ = 16 − m + 1 > 0 ⇔ m < 17.","x₁² + x₂² = 64 − 2(m − 1) = 74 ⇒ m = -4 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 48°. Tính số đo góc ABC (độ).","a":"42","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 48° = 42°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 90 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 102 cm. Tính độ dài MA (cm).","a":"48","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(10404 − 8100) = 48 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 9 cm), góc ở tâm AOB = 30°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"4.71","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 9 × 30 : 180 ≈ 4,71 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 7. Tìm giá trị nhỏ nhất của P = x + 17/x.","a":"66/7","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √17.","s":["Với x ≥ 7 > √17, P tăng theo x.","Pmin = P(7) = 7 + 17/7 = 66/7."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_y6":{"y":2020,"title":"Đề mô phỏng tuyển sinh vào lớp 10 Hà Nội năm học 2020–2021 · môn Toán","note":"Cấu trúc đề Hà Nội giai đoạn 2019–2024: Bài I rút gọn biểu thức (2 đ), Bài II giải toán bằng cách lập phương trình/hệ + hình học thực tế (2,5 đ), Bài III hệ phương trình và parabol (2 đ), Bài IV hình học đường tròn (3 đ), Bài V cực trị (0,5 đ). 120 phút.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 3)/(√x − 4) với x ≥ 0, x ≠ 16. Tính giá trị của A khi x = 324 (viết dạng a/b nếu không nguyên).","a":"3/2","f":true,"p":0.5,"h":"√324 = 18.","s":["A = (18 + 3)/(18 − 4) = 3/2."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 5) + 3√x/(√x − 5) − (4x + 3√x + 35)/(x − 25) với x ≥ 0, x ≠ 25. Rút gọn B ta được","o":["B = 7√x/(√x + 5)","B = (√x + 7)/(√x + 5)","B = 7/(√x − 5)","B = 7/(√x + 5)"],"a":3,"p":1,"h":"Quy đồng với mẫu chung x − 25 = (√x − 5)(√x + 5).","s":["Tử số sau khi quy đồng: 7√x − 35 = 7(√x − 5).","B = 7(√x − 5)/[(√x − 5)(√x + 5)] = 7/(√x + 5)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 7/(√x + 5) (x ≥ 0, x ≠ 25), có bao nhiêu số nguyên x để B > 1?","a":"4","f":true,"p":0.5,"h":"B > 1 ⇔ √x + 5 < 7.","s":["√x < 2 ⇔ 0 ≤ x < 4.","Có 4 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 35 bông hoa gồm hoa hồng và hoa cúc hết 700 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"14","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 35; 35x + 10y = 700.","x = 14, y = 21."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 35 bông hoa, 700 nghìn đồng, hồng 35 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"21","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["35 − 14 = 21."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 9 m và diện tích 580 m². Tính chiều rộng mảnh vườn (m).","a":"20","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 9) = 580 ⇔ x² + 9x − 580 = 0.","x = 20 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 0,4 m, chiều cao 1,8 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"0.9","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 0,4² × 1,8 ≈ 0,9 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 5/(x − 1) + 6/(y + 1) = 49/40 và 4/(x − 1) − 3/(y + 1) = 1/5. Tính x + y.","a":"18","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/8, v = 1/10.","x = 9, y = 9 ⇒ x + y = 18."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 8x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 88.","a":"-11","f":true,"p":1,"h":"Phương trình hoành độ x² − 8x + m − 1 = 0.","s":["Δ′ = 16 − m + 1 > 0 ⇔ m < 17.","x₁² + x₂² = 64 − 2(m − 1) = 88 ⇒ m = -11 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 67°. Tính số đo góc ABC (độ).","a":"23","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 67° = 23°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 16 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 34 cm. Tính độ dài MA (cm).","a":"30","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(1156 − 256) = 30 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 7 cm), góc ở tâm AOB = 150°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"18.32","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 7 × 150 : 180 ≈ 18,32 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 7. Tìm giá trị nhỏ nhất của P = x + 18/x.","a":"67/7","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √18.","s":["Với x ≥ 7 > √18, P tăng theo x.","Pmin = P(7) = 7 + 18/7 = 67/7."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_x0":{"y":0,"lab":"Đề luyện 1","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 1 – cấu trúc từ 2025","note":"Đề luyện thêm theo cấu trúc mới: 5 bài tự luận, 120 phút, thang 10.","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 50 học sinh được ghép nhóm: [140; 145): 19; [145; 150): 6; [150; 155): 9; [155; 160): 7; [160; 165): 9. Tần số tương đối của nhóm [155; 160) là bao nhiêu phần trăm?","a":"14","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["7 : 50 × 100% = 14%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 35 tấm thẻ đánh số từ 1 đến 35. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 6 (viết dạng a/b tối giản).","a":"1/7","f":true,"p":0.75,"h":"Đếm các bội của 6.","s":["Có 5 bội của 6 từ 1 đến 35.","P = 5/35 = 1/7."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 1)/(√x − 2) với x ≥ 0, x ≠ 4. Tính giá trị của A khi x = 100 (viết dạng a/b nếu không nguyên).","a":"11/8","f":true,"p":0.5,"h":"√100 = 10.","s":["A = (10 + 1)/(10 − 2) = 11/8."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 6) + 4√x/(√x − 6) − (5x + 10√x + 48)/(x − 36) với x ≥ 0, x ≠ 36. Rút gọn B ta được","o":["B = 8/(√x + 6)","B = 8√x/(√x + 6)","B = (√x + 8)/(√x + 6)","B = 8/(√x − 6)"],"a":0,"p":0.5,"h":"Quy đồng với mẫu chung x − 36 = (√x − 6)(√x + 6).","s":["Tử số sau khi quy đồng: 8√x − 48 = 8(√x − 6).","B = 8(√x − 6)/[(√x − 6)(√x + 6)] = 8/(√x + 6)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 8/(√x + 6) (x ≥ 0, x ≠ 36), có bao nhiêu số nguyên x để B > 8/9?","a":"9","f":true,"p":0.5,"h":"B > 8/9 ⇔ √x + 6 < 9.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Có 9 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 29 bông hoa gồm hoa hồng và hoa cúc hết 675 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 18 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"9","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 29; 35x + 18y = 675.","x = 9, y = 20."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 29 bông hoa, 675 nghìn đồng, hồng 35 nghìn, cúc 18 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"20","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["29 − 9 = 20."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 8 m và diện tích 609 m². Tính chiều rộng mảnh vườn (m).","a":"21","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 8) = 609 ⇔ x² + 8x − 609 = 0.","x = 21 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 11x + 8 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"105","f":true,"p":0.5,"h":"x₁ + x₂ = 11, x₁x₂ = 8.","s":["(x₁ + x₂)² − 2x₁x₂ = 121 − 16 = 105."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình nón thực tế","q":"Một chiếc nón lá có dạng hình nón với bán kính đáy 4 dm, chiều cao 15 dm. Tính thể tích phần không gian bên trong nón (dm³), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"251.2","f":true,"p":1,"h":"V = πr²h/3.","s":["3,14 × 4² × 15 : 3 ≈ 251,2."],"m":"Nón bằng 1/3 trụ cùng đáy, cùng cao."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 52°. Tính số đo góc ABC (độ).","a":"38","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 52° = 38°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 12 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 15 cm. Tính độ dài MA (cm).","a":"9","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(225 − 144) = 9 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 16 cm), góc ở tâm AOB = 60°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"16.75","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 16 × 60 : 180 ≈ 16,75 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 284 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"10082","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(284 − 2x), lớn nhất khi x = 71.","Smax = 71 × 142 = 10082 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_x1":{"y":0,"lab":"Đề luyện 2","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 2 – cấu trúc từ 2025","note":"Đề luyện thêm theo cấu trúc mới: 5 bài tự luận, 120 phút, thang 10.","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 40 học sinh được ghép nhóm: [140; 145): 10; [145; 150): 6; [150; 155): 10; [155; 160): 10; [160; 165): 4. Tần số tương đối của nhóm [145; 150) là bao nhiêu phần trăm?","a":"15","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["6 : 40 × 100% = 15%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 80 tấm thẻ đánh số từ 1 đến 80. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 7 (viết dạng a/b tối giản).","a":"11/80","f":true,"p":0.75,"h":"Đếm các bội của 7.","s":["Có 11 bội của 7 từ 1 đến 80.","P = 11/80 = 11/80."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 7)/(√x − 4) với x ≥ 0, x ≠ 16. Tính giá trị của A khi x = 144 (viết dạng a/b nếu không nguyên).","a":"19/8","f":true,"p":0.5,"h":"√144 = 12.","s":["A = (12 + 7)/(12 − 4) = 19/8."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 2) + 2√x/(√x − 2) − (3x − 3√x + 10)/(x − 4) với x ≥ 0, x ≠ 4. Rút gọn B ta được","o":["B = 5√x/(√x + 2)","B = 5/(√x + 2)","B = (√x + 5)/(√x + 2)","B = 5/(√x − 2)"],"a":1,"p":0.5,"h":"Quy đồng với mẫu chung x − 4 = (√x − 2)(√x + 2).","s":["Tử số sau khi quy đồng: 5√x − 10 = 5(√x − 2).","B = 5(√x − 2)/[(√x − 2)(√x + 2)] = 5/(√x + 2)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 5/(√x + 2) (x ≥ 0, x ≠ 4), có bao nhiêu số nguyên x để B > 1?","a":"8","f":true,"p":0.5,"h":"B > 1 ⇔ √x + 2 < 5.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Loại x = 4.","Có 8 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 46 bông hoa gồm hoa hồng và hoa cúc hết 492 nghìn đồng. Giá một bông hồng là 12 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"16","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 46; 12x + 10y = 492.","x = 16, y = 30."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 46 bông hoa, 492 nghìn đồng, hồng 12 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"30","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["46 − 16 = 30."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 6 m và diện tích 720 m². Tính chiều rộng mảnh vườn (m).","a":"24","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 6) = 720 ⇔ x² + 6x − 720 = 0.","x = 24 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 4x + 1 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"14","f":true,"p":0.5,"h":"x₁ + x₂ = 4, x₁x₂ = 1.","s":["(x₁ + x₂)² − 2x₁x₂ = 16 − 2 = 14."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình nón thực tế","q":"Một chiếc nón lá có dạng hình nón với bán kính đáy 2 dm, chiều cao 3 dm. Tính thể tích phần không gian bên trong nón (dm³), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"12.56","f":true,"p":1,"h":"V = πr²h/3.","s":["3,14 × 2² × 3 : 3 ≈ 12,56."],"m":"Nón bằng 1/3 trụ cùng đáy, cùng cao."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 50°. Tính số đo góc ABC (độ).","a":"40","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 50° = 40°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 16 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 20 cm. Tính độ dài MA (cm).","a":"12","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(400 − 256) = 12 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 7 cm), góc ở tâm AOB = 120°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"14.65","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 7 × 120 : 180 ≈ 14,65 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 176 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"3872","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(176 − 2x), lớn nhất khi x = 44.","Smax = 44 × 88 = 3872 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_x2":{"y":0,"lab":"Đề luyện 3","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 3 – cấu trúc từ 2025","note":"Đề luyện thêm theo cấu trúc mới: 5 bài tự luận, 120 phút, thang 10.","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 50 học sinh được ghép nhóm: [140; 145): 18; [145; 150): 10; [150; 155): 9; [155; 160): 7; [160; 165): 6. Tần số tương đối của nhóm [155; 160) là bao nhiêu phần trăm?","a":"14","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["7 : 50 × 100% = 14%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 50 tấm thẻ đánh số từ 1 đến 50. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 7 (viết dạng a/b tối giản).","a":"7/50","f":true,"p":0.75,"h":"Đếm các bội của 7.","s":["Có 7 bội của 7 từ 1 đến 50.","P = 7/50 = 7/50."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 8)/(√x − 5) với x ≥ 0, x ≠ 25. Tính giá trị của A khi x = 289 (viết dạng a/b nếu không nguyên).","a":"25/12","f":true,"p":0.5,"h":"√289 = 17.","s":["A = (17 + 8)/(17 − 5) = 25/12."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 5) + √x/(√x − 5) − (2x − 12√x + 60)/(x − 25) với x ≥ 0, x ≠ 25. Rút gọn B ta được","o":["B = 12/(√x − 5)","B = 12√x/(√x + 5)","B = 12/(√x + 5)","B = (√x + 12)/(√x + 5)"],"a":2,"p":0.5,"h":"Quy đồng với mẫu chung x − 25 = (√x − 5)(√x + 5).","s":["Tử số sau khi quy đồng: 12√x − 60 = 12(√x − 5).","B = 12(√x − 5)/[(√x − 5)(√x + 5)] = 12/(√x + 5)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 12/(√x + 5) (x ≥ 0, x ≠ 25), có bao nhiêu số nguyên x để B > 3/2?","a":"9","f":true,"p":0.5,"h":"B > 3/2 ⇔ √x + 5 < 8.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Có 9 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 40 bông hoa gồm hoa hồng và hoa cúc hết 725 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 8 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"15","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 40; 35x + 8y = 725.","x = 15, y = 25."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 40 bông hoa, 725 nghìn đồng, hồng 35 nghìn, cúc 8 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"25","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["40 − 15 = 25."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 6 m và diện tích 567 m². Tính chiều rộng mảnh vườn (m).","a":"21","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 6) = 567 ⇔ x² + 6x − 567 = 0.","x = 21 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 5x + 4 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"17","f":true,"p":0.5,"h":"x₁ + x₂ = 5, x₁x₂ = 4.","s":["(x₁ + x₂)² − 2x₁x₂ = 25 − 8 = 17."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 0,8 m, chiều cao 3,5 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"7.03","f":true,"p":1,"h":"V = πr²h.","s":["3,14 × 0,8² × 3,5 ≈ 7,03 m³."],"m":"Bình phương bán kính, không phải đường kính."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 15°. Tính số đo góc ABC (độ).","a":"75","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 15° = 75°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 25 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 65 cm. Tính độ dài MA (cm).","a":"60","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(4225 − 625) = 60 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 8 cm), góc ở tâm AOB = 90°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"12.56","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 8 × 90 : 180 ≈ 12,56 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 132 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"2178","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(132 − 2x), lớn nhất khi x = 33.","Smax = 33 × 66 = 2178 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_x3":{"y":0,"lab":"Đề luyện 4","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 4 – cấu trúc từ 2025","note":"Đề luyện thêm theo cấu trúc mới: 5 bài tự luận, 120 phút, thang 10.","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 40 học sinh được ghép nhóm: [140; 145): 12; [145; 150): 6; [150; 155): 6; [155; 160): 8; [160; 165): 8. Tần số tương đối của nhóm [145; 150) là bao nhiêu phần trăm?","a":"15","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["6 : 40 × 100% = 15%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 55 tấm thẻ đánh số từ 1 đến 55. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 5 (viết dạng a/b tối giản).","a":"1/5","f":true,"p":0.75,"h":"Đếm các bội của 5.","s":["Có 11 bội của 5 từ 1 đến 55.","P = 11/55 = 1/5."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 1)/(√x − 2) với x ≥ 0, x ≠ 4. Tính giá trị của A khi x = 36 (viết dạng a/b nếu không nguyên).","a":"7/4","f":true,"p":0.5,"h":"√36 = 6.","s":["A = (6 + 1)/(6 − 2) = 7/4."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 3) + √x/(√x − 3) − (2x − 2√x + 6)/(x − 9) với x ≥ 0, x ≠ 9. Rút gọn B ta được","o":["B = (√x + 2)/(√x + 3)","B = 2√x/(√x + 3)","B = 2/(√x − 3)","B = 2/(√x + 3)"],"a":3,"p":0.5,"h":"Quy đồng với mẫu chung x − 9 = (√x − 3)(√x + 3).","s":["Tử số sau khi quy đồng: 2√x − 6 = 2(√x − 3).","B = 2(√x − 3)/[(√x − 3)(√x + 3)] = 2/(√x + 3)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 2/(√x + 3) (x ≥ 0, x ≠ 9), có bao nhiêu số nguyên x để B > 2/5?","a":"4","f":true,"p":0.5,"h":"B > 2/5 ⇔ √x + 3 < 5.","s":["√x < 2 ⇔ 0 ≤ x < 4.","Có 4 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 42 bông hoa gồm hoa hồng và hoa cúc hết 1171 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 12 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"29","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 42; 35x + 12y = 1171.","x = 29, y = 13."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 42 bông hoa, 1171 nghìn đồng, hồng 35 nghìn, cúc 12 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"13","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["42 − 29 = 13."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 8 m và diện tích 768 m². Tính chiều rộng mảnh vườn (m).","a":"24","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 8) = 768 ⇔ x² + 8x − 768 = 0.","x = 24 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 12x + 8 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"128","f":true,"p":0.5,"h":"x₁ + x₂ = 12, x₁x₂ = 8.","s":["(x₁ + x₂)² − 2x₁x₂ = 144 − 16 = 128."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 0,3 m, chiều cao 3 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"0.85","f":true,"p":1,"h":"V = πr²h.","s":["3,14 × 0,3² × 3 ≈ 0,85 m³."],"m":"Bình phương bán kính, không phải đường kính."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 34°. Tính số đo góc ABC (độ).","a":"56","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 34° = 56°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 6 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 10 cm. Tính độ dài MA (cm).","a":"8","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(100 − 36) = 8 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 18 cm), góc ở tâm AOB = 40°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"12.56","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 18 × 40 : 180 ≈ 12,56 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 292 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"10658","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(292 − 2x), lớn nhất khi x = 73.","Smax = 73 × 146 = 10658 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_x4":{"y":0,"lab":"Đề luyện 5","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 5 – cấu trúc từ 2025","note":"Đề luyện thêm theo cấu trúc mới: 5 bài tự luận, 120 phút, thang 10.","parts":[["Bài I (1,5 điểm) · Thống kê và xác suất",[{"t":"Tổ hợp","d":"Thống kê ghép nhóm","q":"Chiều cao (cm) của 40 học sinh được ghép nhóm: [140; 145): 19; [145; 150): 5; [150; 155): 4; [155; 160): 5; [160; 165): 7. Tần số tương đối của nhóm [150; 155) là bao nhiêu phần trăm?","a":"10","f":true,"p":0.75,"h":"Tần số tương đối = tần số : tổng × 100%.","s":["4 : 40 × 100% = 10%."],"m":"Tổng tần số bằng số học sinh."},{"t":"Tổ hợp","d":"Xác suất","q":"Một hộp có 45 tấm thẻ đánh số từ 1 đến 45. Rút ngẫu nhiên một thẻ. Tính xác suất thẻ rút được mang số chia hết cho 5 (viết dạng a/b tối giản).","a":"1/5","f":true,"p":0.75,"h":"Đếm các bội của 5.","s":["Có 9 bội của 5 từ 1 đến 45.","P = 9/45 = 1/5."],"m":"Xác suất = số kết quả thuận lợi : số kết quả có thể."}]],["Bài II (1,5 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 3)/(√x − 1) với x ≥ 0, x ≠ 1. Tính giá trị của A khi x = 81 (viết dạng a/b nếu không nguyên).","a":"3/2","f":true,"p":0.5,"h":"√81 = 9.","s":["A = (9 + 3)/(9 − 1) = 3/2."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 2) + √x/(√x − 2) − (2x − 12√x + 24)/(x − 4) với x ≥ 0, x ≠ 4. Rút gọn B ta được","o":["B = (√x + 12)/(√x + 2)","B = 12/(√x + 2)","B = 12√x/(√x + 2)","B = 12/(√x − 2)"],"a":1,"p":0.5,"h":"Quy đồng với mẫu chung x − 4 = (√x − 2)(√x + 2).","s":["Tử số sau khi quy đồng: 12√x − 24 = 12(√x − 2).","B = 12(√x − 2)/[(√x − 2)(√x + 2)] = 12/(√x + 2)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 12/(√x + 2) (x ≥ 0, x ≠ 4), có bao nhiêu số nguyên x để B > 12/5?","a":"8","f":true,"p":0.5,"h":"B > 12/5 ⇔ √x + 2 < 5.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Loại x = 4.","Có 8 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài III (2,5 điểm) · Bài toán thực tế; phương trình bậc hai",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 23 bông hoa gồm hoa hồng và hoa cúc hết 285 nghìn đồng. Giá một bông hồng là 15 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"11","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 23; 15x + 10y = 285.","x = 11, y = 12."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 23 bông hoa, 285 nghìn đồng, hồng 15 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"12","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["23 − 11 = 12."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Phương trình bậc hai thực tế","q":"Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng 6 m và diện tích 187 m². Tính chiều rộng mảnh vườn (m).","a":"11","f":true,"p":1,"h":"Gọi chiều rộng là x > 0.","s":["x(x + 6) = 187 ⇔ x² + 6x − 187 = 0.","x = 11 (loại nghiệm âm)."],"m":"Loại nghiệm không thỏa điều kiện."},{"t":"Đại số","d":"Hệ thức Vi-ét","q":"Phương trình x² − 6x + 4 = 0 có hai nghiệm x₁, x₂. Tính x₁² + x₂².","a":"28","f":true,"p":0.5,"h":"x₁ + x₂ = 6, x₁x₂ = 4.","s":["(x₁ + x₂)² − 2x₁x₂ = 36 − 8 = 28."],"m":"Không cần giải phương trình."}]],["Bài IV (4 điểm) · Hình học thực tế và đường tròn",[{"t":"Hình học","d":"Hình nón thực tế","q":"Một chiếc nón lá có dạng hình nón với bán kính đáy 7 dm, chiều cao 12 dm. Tính thể tích phần không gian bên trong nón (dm³), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"615.44","f":true,"p":1,"h":"V = πr²h/3.","s":["3,14 × 7² × 12 : 3 ≈ 615,44."],"m":"Nón bằng 1/3 trụ cùng đáy, cùng cao."},{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 71°. Tính số đo góc ABC (độ).","a":"19","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 71° = 19°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 75 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 85 cm. Tính độ dài MA (cm).","a":"40","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(7225 − 5625) = 40 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 8 cm), góc ở tâm AOB = 60°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"8.37","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 8 × 60 : 180 ≈ 8,37 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Tối ưu thực tế",[{"t":"Đại số","d":"Tối ưu thực tế","q":"Bác An có 400 m lưới để rào một khu vườn hình chữ nhật, một cạnh tựa vào bức tường (không cần rào). Diện tích lớn nhất có thể rào được là bao nhiêu m²?","a":"20000","f":true,"p":0.5,"h":"Gọi cạnh vuông góc với tường là x.","s":["S = x(400 − 2x), lớn nhất khi x = 100.","Smax = 100 × 200 = 20000 m²."],"m":"Biến đổi về dạng bình phương hoặc dùng Cô-si."}]]]},"S_v_x5":{"y":0,"lab":"Đề luyện cũ 1","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 1 – cấu trúc 2019–2024","note":"Đề luyện thêm theo cấu trúc cũ: rút gọn biểu thức, lập phương trình/hệ, hệ phương trình và parabol, hình học đường tròn, cực trị.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 6)/(√x − 5) với x ≥ 0, x ≠ 25. Tính giá trị của A khi x = 81 (viết dạng a/b nếu không nguyên).","a":"15/4","f":true,"p":0.5,"h":"√81 = 9.","s":["A = (9 + 6)/(9 − 5) = 15/4."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 2) + 4√x/(√x − 2) − (5x − 5√x + 22)/(x − 4) với x ≥ 0, x ≠ 4. Rút gọn B ta được","o":["B = 11/(√x + 2)","B = 11√x/(√x + 2)","B = (√x + 11)/(√x + 2)","B = 11/(√x − 2)"],"a":0,"p":1,"h":"Quy đồng với mẫu chung x − 4 = (√x − 2)(√x + 2).","s":["Tử số sau khi quy đồng: 11√x − 22 = 11(√x − 2).","B = 11(√x − 2)/[(√x − 2)(√x + 2)] = 11/(√x + 2)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 11/(√x + 2) (x ≥ 0, x ≠ 4), có bao nhiêu số nguyên x để B > 11/5?","a":"8","f":true,"p":0.5,"h":"B > 11/5 ⇔ √x + 2 < 5.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Loại x = 4.","Có 8 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 35 bông hoa gồm hoa hồng và hoa cúc hết 735 nghìn đồng. Giá một bông hồng là 30 nghìn, một bông cúc là 15 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"14","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 35; 30x + 15y = 735.","x = 14, y = 21."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 35 bông hoa, 735 nghìn đồng, hồng 30 nghìn, cúc 15 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"21","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["35 − 14 = 21."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Bài toán làm chung","q":"Hai vòi nước cùng chảy vào một bể cạn. Vòi thứ nhất chảy riêng đầy bể trong 29 giờ, vòi thứ hai trong 19 giờ. Hỏi cả hai vòi cùng chảy thì bao nhiêu giờ đầy bể?","a":"551/48","f":true,"p":1,"h":"Cộng năng suất mỗi giờ.","s":["1/29 + 1/19 = 48/551 bể/giờ.","Thời gian: 551/48 giờ."],"m":"Năng suất là phần bể mỗi giờ."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 1,3 m, chiều cao 1,6 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"8.49","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 1,3² × 1,6 ≈ 8,49 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 5/(x − 1) + 3/(y + 1) = 26/7 và 5/(x − 1) + 1/(y + 1) = 12/7. Tính x + y.","a":"8","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/7, v = 1.","x = 8, y = 0 ⇒ x + y = 8."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 6x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 58.","a":"-10","f":true,"p":1,"h":"Phương trình hoành độ x² − 6x + m − 1 = 0.","s":["Δ′ = 9 − m + 1 > 0 ⇔ m < 10.","x₁² + x₂² = 36 − 2(m − 1) = 58 ⇒ m = -10 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 31°. Tính số đo góc ABC (độ).","a":"59","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 31° = 59°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 35 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 125 cm. Tính độ dài MA (cm).","a":"120","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(15625 − 1225) = 120 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 8 cm), góc ở tâm AOB = 20°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"2.79","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 8 × 20 : 180 ≈ 2,79 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 3. Tìm giá trị nhỏ nhất của P = x + 5/x.","a":"14/3","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √5.","s":["Với x ≥ 3 > √5, P tăng theo x.","Pmin = P(3) = 3 + 5/3 = 14/3."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]},"S_v_x6":{"y":0,"lab":"Đề luyện cũ 2","title":"Đề luyện vào lớp 10 Hà Nội môn Toán số 2 – cấu trúc 2019–2024","note":"Đề luyện thêm theo cấu trúc cũ: rút gọn biểu thức, lập phương trình/hệ, hệ phương trình và parabol, hình học đường tròn, cực trị.","parts":[["Bài I (2 điểm) · Biểu thức chứa căn",[{"t":"Đại số","d":"Biểu thức chứa căn","q":"Cho A = (√x + 3)/(√x − 1) với x ≥ 0, x ≠ 1. Tính giá trị của A khi x = 400 (viết dạng a/b nếu không nguyên).","a":"23/19","f":true,"p":0.5,"h":"√400 = 20.","s":["A = (20 + 3)/(20 − 1) = 23/19."],"m":"Thay √x trước khi tính."},{"t":"Đại số","d":"Rút gọn biểu thức","q":"Cho B = √x/(√x + 6) + √x/(√x − 6) − (2x − 11√x + 66)/(x − 36) với x ≥ 0, x ≠ 36. Rút gọn B ta được","o":["B = (√x + 11)/(√x + 6)","B = 11/(√x − 6)","B = 11/(√x + 6)","B = 11√x/(√x + 6)"],"a":2,"p":1,"h":"Quy đồng với mẫu chung x − 36 = (√x − 6)(√x + 6).","s":["Tử số sau khi quy đồng: 11√x − 66 = 11(√x − 6).","B = 11(√x − 6)/[(√x − 6)(√x + 6)] = 11/(√x + 6)."],"m":"Phân tích x − k² = (√x − k)(√x + k)."},{"t":"Đại số","d":"Bất phương trình chứa căn","q":"Với B = 11/(√x + 6) (x ≥ 0, x ≠ 36), có bao nhiêu số nguyên x để B > 11/9?","a":"9","f":true,"p":0.5,"h":"B > 11/9 ⇔ √x + 6 < 9.","s":["√x < 3 ⇔ 0 ≤ x < 9.","Có 9 số nguyên."],"m":"Nhớ điều kiện xác định."}]],["Bài II (2,5 điểm) · Giải bài toán bằng cách lập phương trình, hệ phương trình",[{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"Một người mua 29 bông hoa gồm hoa hồng và hoa cúc hết 765 nghìn đồng. Giá một bông hồng là 35 nghìn, một bông cúc là 10 nghìn. Người đó mua bao nhiêu bông hoa hồng?","a":"19","f":true,"p":0.5,"h":"Gọi x, y là số hoa hồng, hoa cúc.","s":["x + y = 29; 35x + 10y = 765.","x = 19, y = 10."],"m":"Kiểm tra lại cả hai phương trình."},{"t":"Đại số","d":"Giải bài toán bằng cách lập hệ","q":"(Tiếp câu trên: 29 bông hoa, 765 nghìn đồng, hồng 35 nghìn, cúc 10 nghìn) Người đó mua bao nhiêu bông hoa cúc?","a":"10","f":true,"p":0.5,"h":"Lấy tổng trừ số hoa hồng.","s":["29 − 19 = 10."],"m":"Trả lời đủ hai ẩn."},{"t":"Đại số","d":"Bài toán làm chung","q":"Hai vòi nước cùng chảy vào một bể cạn. Vòi thứ nhất chảy riêng đầy bể trong 24 giờ, vòi thứ hai trong 6 giờ. Hỏi cả hai vòi cùng chảy thì bao nhiêu giờ đầy bể?","a":"24/5","f":true,"p":1,"h":"Cộng năng suất mỗi giờ.","s":["1/24 + 1/6 = 5/24 bể/giờ.","Thời gian: 24/5 giờ."],"m":"Năng suất là phần bể mỗi giờ."},{"t":"Hình học","d":"Hình trụ thực tế","q":"Một bồn nước hình trụ có bán kính đáy 0,5 m, chiều cao 3,9 m. Tính thể tích bồn (m³), lấy π ≈ 3,14 và làm tròn đến hàng phần trăm.","a":"3.06","f":true,"p":0.5,"h":"V = πr²h.","s":["3,14 × 0,5² × 3,9 ≈ 3,06 m³."],"m":"Bình phương bán kính, không phải đường kính."}]],["Bài III (2 điểm) · Hệ phương trình; parabol và đường thẳng",[{"t":"Đại số","d":"Hệ phương trình","q":"Giải hệ phương trình: 6/(x − 1) + 3/(y + 1) = 11/6 và 4/(x − 1) + 3/(y + 1) = 4/3. Tính x + y.","a":"13","f":true,"p":1,"h":"Đặt u = 1/(x − 1), v = 1/(y + 1).","s":["Giải được u = 1/4, v = 1/9.","x = 5, y = 8 ⇒ x + y = 13."],"m":"Đặt ẩn phụ rồi đổi lại."},{"t":"Đại số","d":"Parabol và đường thẳng","q":"Cho (P): y = x² và d: y = 2x − m + 1. Tìm m để d cắt (P) tại hai điểm phân biệt có hoành độ x₁, x₂ thỏa x₁² + x₂² = 8.","a":"-1","f":true,"p":1,"h":"Phương trình hoành độ x² − 2x + m − 1 = 0.","s":["Δ′ = 1 − m + 1 > 0 ⇔ m < 2.","x₁² + x₂² = 4 − 2(m − 1) = 8 ⇒ m = -1 (thỏa)."],"m":"Kiểm tra điều kiện Δ."}]],["Bài IV (3 điểm) · Hình học đường tròn",[{"t":"Hình học","d":"Góc nội tiếp","q":"Cho đường tròn (O) đường kính AB, điểm C thuộc đường tròn sao cho góc CAB = 26°. Tính số đo góc ABC (độ).","a":"64","f":true,"p":1,"h":"Góc nội tiếp chắn nửa đường tròn.","s":["Góc ACB = 90° ⇒ góc ABC = 90° − 26° = 64°."],"m":"Góc nội tiếp chắn nửa đường tròn là góc vuông."},{"t":"Hình học","d":"Tiếp tuyến","q":"Từ điểm M nằm ngoài đường tròn (O; 24 cm) kẻ tiếp tuyến MA (A là tiếp điểm). Biết OM = 30 cm. Tính độ dài MA (cm).","a":"18","f":true,"p":1,"h":"OA ⊥ MA.","s":["MA = √(OM² − OA²) = √(900 − 576) = 18 cm."],"m":"Bán kính vuông góc với tiếp tuyến tại tiếp điểm."},{"t":"Hình học","d":"Độ dài cung","q":"Trên đường tròn (O; 15 cm), góc ở tâm AOB = 36°. Tính độ dài cung nhỏ AB (cm), lấy π ≈ 3,14, làm tròn đến hàng phần trăm.","a":"9.42","f":true,"p":1,"h":"l = πRn/180.","s":["3,14 × 15 × 36 : 180 ≈ 9,42 cm."],"m":"Độ dài cung tỉ lệ với số đo góc ở tâm."}]],["Bài V (0,5 điểm) · Giá trị nhỏ nhất",[{"t":"Đại số","d":"Giá trị nhỏ nhất","q":"Cho x ≥ 7. Tìm giá trị nhỏ nhất của P = x + 23/x.","a":"72/7","f":true,"p":0.5,"h":"P đồng biến khi x ≥ √23.","s":["Với x ≥ 7 > √23, P tăng theo x.","Pmin = P(7) = 7 + 23/7 = 72/7."],"m":"Điểm rơi của Cô-si nằm ngoài miền thì xét tại đầu mút."}]]]}});
